A_6U = 0.22; %m^2
m_6U = 12; %kg
I_6U = 0.12; %kg.m^2
Kp = 0.1; %gain of Proportional controller in kg.m^2

theta0 = 0; omega0 = 0; torque0 = 0;
target_theta = 0.52;

params.A_6U=A_6U; params.m_6U=m_6U; params.I=I_6U; params.kp=Kp;
params.theta0 = theta0; params.omega0 = omega0; params.tau0 = torque0;
params.t_theta = target_theta;

%L/I = domega/dt
%tau/I = dwdt


%T=0.5*I*omega^2
F = -Kp*target_theta

tspan = [0 60];
Y0 = [params.theta0; params.omega0];

opts = odeset('RelTol',1e-6,'AbsTol',1e-9);
[t,st] = ode45(@(t,st) rotational_motion(t,st,params), tspan, Y0, opts); %St are states

figure; %[output:0a3e06d6]
plot(t,st(:,1)) %[output:0a3e06d6]
xlabel("time (s)") %[output:0a3e06d6]
ylabel("states") %[output:0a3e06d6]
legend("\theta") %[output:0a3e06d6]
plot(t,st(:,2),'r') %[output:738e4f34]
legend("\omega") %[output:738e4f34]
peak_w = target_theta*sqrt(Kp/I) %[output:9a02733f]

function domegadt = rotational_motion(t,st,params)

theta=st(1); omega=st(2);
tau=params.kp*(params.t_theta-theta);
dtheta=omega;
domega = tau / params.I;
domegadt=[dtheta; domega];


end

%P controller: used to modify torque at each instant to reach a target
%angle, where error = target angle - current angle
%gain (Kp): how strongly the P controller affects torque - constant

